  'console.ecran.service.in.regles.critique.quand': 'SkanFact est arrêté, des données sont en danger, ou un chiffre faux est parti chez des clients',
  'console.ecran.service.in.regles.critique.r1': 'toute l\'équipe est prévenue ; la direction décide',
  'console.ecran.service.in.regles.critique.r2': 'page d\'état dans les dix minutes',
  'console.ecran.service.in.regles.critique.r3': 'le compte rendu part aux entreprises touchées',
  'console.ecran.service.in.regles.pied': 'pour tous : le compte rendu s\'écrit dans les deux jours ouvrés ; chaque suite a une personne et une date ; un compte rendu ne cherche pas un coupable. Ces règles sont proposées : la console ne prévient personne d\'elle-même (les alertes de la veille, si)',
  'console.ecran.service.in.fiches.titre': 'les fiches réflexes',
  'console.ecran.service.in.fiches.sous': 'ce qu\'on fait, dans l\'ordre, quand ça arrive. Écrites à froid, pour ne pas avoir à réfléchir à chaud',
  'console.ecran.service.in.fiches.abord': 'D\'abord :',
  'console.ecran.service.in.fiches.lire': 'lire la fiche · 4 temps',
  'console.ecran.service.in.fiches.servie': 'servie le {jour}',
  'console.ecran.service.in.fiches.exercee': 'exercée le {jour}',
  'console.ecran.service.in.fiches.jamais': 'jamais servie',
  'console.ecran.service.in.fiches.a_decider_dit': 'cette fiche dépend d\'une décision qui n\'est pas prise (un site de secours) : elle dit ce qu\'on ferait, pas ce qui est prêt',
  'console.ecran.service.in.fiches.a_verifier_dit': 'cette fiche touche au droit (la loi sur les données personnelles, l\'INPDP) : ce qu\'elle dit des déclarations est à vérifier avec un juriste',
  'console.ecran.service.in.temps.contenir': '1. Contenir',
